function key(ctx){if(ctx.type==='question')return ctx.pageId;if(ctx.type==='entry')return'menu:welcome';const r=ctx.route||{};if(r.view==='library')return'menu:library:'+r.grade+':'+(r.topic||'all')+':'+(r.strandOverview?'strands':'activities')+':'+((r.page||0)+1);return'menu:'+(r.kind||'homework')+':'+(r.week||'2026-10-19')+':'+r.grade+':'+(r.day==null?'week':r.day)+':'+(r.set==null?'sets':r.set)}
for(const q of window.ML_NOVEMBER_ADDITION?.pages||[])registry.pages[q.id]={code:q.pageCode,prefix:q.pageCode.slice(0,2),grade:q.grade,title:q.title};
const byCode=new Map(Object.entries(registry.pages).map(([id,p])=>[p.code,id]));const api={idForCode:value=>byCode.get(String(value||'').toUpperCase())||'',forNote:n=>code(n.pageId)||code(key(n)),get:code,forContext:ctx=>code(key(ctx)),key,registry};api.stampPNG=async(png,value)=>{if(!value)return png;await document.fonts.ready;const img=new Image();img.src=png;await img.decode();const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const ctx=c.getContext('2d');ctx.drawImage(img,0,0);ctx.font='bold 12px Andika';const w=ctx.measureText(value).width+14,x=c.width-w-6,y=c.height-22;ctx.fillStyle='#fffef5';ctx.fillRect(x,y,w,18);ctx.fillStyle='#526f6b';ctx.fillText(value,x+7,y+13);return window.ML_INDEXED_PNG?await ML_INDEXED_PNG(c):c.toDataURL('image/png')};window.ML_PAGE_CODES=api;for(const q of[...(window.ML_CATALOG||[]),...(window.ML_HOMEWORK_PAGES||[])]){q.pageCode=code(q.id);q.config.pageCode=q.pageCode;}
function childBadge(){const cfg=window.ML_CONFIG;if(!cfg?.pageCode)return;const b=document.createElement('small');b.id='mlActivityPageCode';b.textContent=cfg.pageCode;b.setAttribute('aria-label','Permanent page code '+cfg.pageCode);document.body.append(b);if(window.ML_ENGINE)for(const name of['get','check']){const fn=ML_ENGINE[name]?.bind(ML_ENGINE);if(!fn)continue;ML_ENGINE[name]=(...args)=>{const result=fn(...args);if(result){result.pageCode=cfg.pageCode;if(result.assessment)result.assessment.pageCode=cfg.pageCode;}return result}}}
const css='#mlActivityPageCode{position:fixed;right:8px;bottom:3px;z-index:50;pointer-events:none;font:10px/1.2 Andika,sans-serif!important;letter-spacing:.04em;color:#526f6b;background:#fffef5e8;padding:2px 5px;border-radius:4px}';for(const[name,h]of Object.entries(window.ML_ENGINES))window.ML_ENGINES[name]=h.replace('</head>','<style>'+css+'</style><script>document.addEventListener("DOMContentLoaded",'+childBadge.toString()+',{once:true});<\/script></head>');
function start(){let badge=document.getElementById('mlMenuPageCode');if(!badge){badge=document.createElement('small');badge.id='mlMenuPageCode';badge.style.cssText='position:fixed;right:12px;bottom:8px;z-index:400;pointer-events:none;font:10px/1.2 Andika,sans-serif;letter-spacing:.04em;color:#526f6b;background:#fffef5e8;padding:2px 5px;border-radius:4px';document.body.append(badge)}let pending=false;function update(){pending=false;const ctx=window.ML_APP?.pageContext?.();if(!ctx)return;const value=api.forContext(ctx);badge.hidden=ctx.type==='question';if(badge.textContent!==value)badge.textContent=value;badge.setAttribute('aria-label','Permanent page code '+value);const dock=document.getElementById('teacherAuditDock');badge.style.bottom=((dock?.getBoundingClientRect().height||0)+7)+'px';}const schedule=()=>{if(!pending){pending=true;requestAnimationFrame(update)}};new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['data-view','data-grade']});addEventListener('resize',schedule);update();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
